def extend(d, add):
    """Append exactly eight focuses to each of the seven requested groups."""
    groups = {g["id"]: g for g in d["groups"]}
    for group_id, branch in BRANCHES.items():
        group = groups[group_id]
        existing = [n for n in d["nodes"] if n.get("group") == group_id]
        x0 = int(group["x"])
        y0 = max(int(n["y"]) for n in existing) + 1
        for key, title, dx, dy, pre, mods, price, icon, description in branch["focuses"]:
            node = add(
                group, key, title, x0 + dx, y0 + dy,
                pre, mods, price, icon, description,
                mutex=next((pair for pair in branch["mutex"] if key in pair), ()),
            )
            # The largest capital programmes use the native 49-day / 7 CP tier.
            if key in {"kdp_civic_settlement", "chondo_harvest_pact", "cabinet_energy_compact", "kpa_defence_charter", "yanan_collective_plan", "union_industrial_compact", "christian_civic_compact"}:
                node["days"] = 49
                node["cost"] = 7
